# -- .grad: per-atom subgradient ----------------------------------
## CVXPY SOURCE: atoms/sum_largest.py:69-99 (sum_largest._grad).
## 1 at each of the floor(k) largest indices; (k - floor(k)) at the
## (floor(k) + 1)-th largest. CVXPY uses argpartition; R's sort with
## index.return is exact (deterministic, slower, fine for our scale).
method(.grad, SumLargest) <- function(x, values, ...) {
  v <- as.numeric(values[[1L]])     # column-major flatten
  n <- length(v)
  k <- x@k
  k_floor <- as.integer(floor(k))
  k_frac  <- k - k_floor

  rows <- as.integer(prod(x@args[[1L]]@shape))
  D <- numeric(rows)

  ## Decreasing-order indices (stable to give CVXPY-equivalent tie-break).
  ord <- order(-v)

  if (k_floor > 0L) {
    D[ord[seq_len(min(k_floor, n))]] <- 1
  }
  if (k_frac > 0 && k_floor < n) {
    D[ord[k_floor + 1L]] <- k_frac
  }

  list(Matrix::sparseMatrix(
    i = which(D != 0),
    j = rep_len(1L, sum(D != 0)),
    x = D[D != 0],
    dims = c(rows, 1L),
    repr = "C"
  ))
}

#' Sum of k largest entries
#'
#' @param x An Expression
#' @param k Number of largest entries to sum
#' @returns A SumLargest atom
#' @export
sum_largest <- function(x, k) {
  SumLargest(x, k)
}
